default:
{{- $all := "" -}}
{{- if gt (len .Authors) 0 -}}
{{-   with first .Authors -}}
{{-     $all = .LastName -}}
{{-     if .FirstName }}{{ $all = (cat $all .FirstName) }}{{- end -}}
{{-     if .MiddleName }}{{ $all = (cat $all .MiddleName) }}{{- end -}}
{{-     if and (not $all) .Nickname }}{{ $all = .Nickname }}{{- end -}}
{{-   end -}}
{{-   if gt (len .Authors) 1 -}}
{{-     if eq .Language "ru" }}{{ $all = (cat $all "и др") }}{{- else -}}{{ $all = (printf "%s%s" $all ", et al") }}{{- end -}}
{{-   end -}}
{{-   $all = cat $all "-" -}}
{{- end -}}
{{- if $all -}}
{{-   cat $all .Title -}}
{{- else -}}
{{-   .Title -}}
{{- end -}}

{{- if gt (len .Series) 0 -}}
{{-   $seriesPath := list -}}
{{-   $seriesNumber := 0 -}}
{{-   $currentParent := -1 -}}
{{-   $hasNested := false -}}
{{-   range .Series -}}
{{-     if ge .Parent 0 -}}{{ $hasNested = true }}{{- end -}}
{{-   end -}}
{{-   range $index, $series := .Series -}}
{{-     if or (not $hasNested) (eq $index 0) (eq $series.Parent $currentParent) -}}
{{-       $seriesLetters := list -}}
{{-       range $word := splitList " " $series.Name -}}
{{-       $seriesLetters = append $seriesLetters (upper (first (splitList "" $word))) -}}
{{-       end -}}
{{-       if gt (len $seriesLetters) 0 -}}
{{-         $seriesPath = append $seriesPath (join "" $seriesLetters) -}}
{{-         $seriesNumber = $series.Number -}}
{{-         $currentParent = $index -}}
{{-       end -}}
{{-     end -}}
{{-   end -}}
{{-   if gt (len $seriesPath) 0 -}}
{{-     "(" }}{{- join "/" $seriesPath -}}
{{-     if gt $seriesNumber 0 -}}
{{-       printf " - %02d" $seriesNumber -}}
{{-     end -}}
{{-     ") " -}}
{{-   end -}}
{{- end -}}
{{  .Title -}}

{{- .LastName -}}
{{- if .FirstName }} {{.FirstName}}{{ end -}}
{{- if .MiddleName }} {{.MiddleName }}{{ end -}}
{{- if and (not .LastName) (not .FirstName) (not .MiddleName) .Nickname }}{{ .Nickname }}{{ end -}}

{{- if eq .Format "pdf" -}}
{{-   if .PageNumber -}}
{{-     printf "[page\u00A0%d]" .PageNumber -}}
{{-   else -}}
{{-     "[<]" -}}
{{-   end -}}
{{- else if or (eq .Format "kfx") (eq .Format "azw8") -}}
{{-   if .LocationNumber -}}
{{-     printf "[loc\u00A0%d]" .LocationNumber -}}
{{-   else if .PageNumber -}}
{{-     printf "[page\u00A0%d]" .PageNumber -}}
{{-   else if .SectionTitle -}}
{{-     printf "[%s]" .SectionTitle -}}
{{-   else -}}
{{-     "[<]" -}}
{{-   end -}}
{{- else -}}
{{-   if .PageNumber -}}
{{-     printf "[page\u00A0%d]" .PageNumber -}}
{{-   else if .SectionTitle -}}
{{-     printf "[%s]" .SectionTitle -}}
{{-   else -}}
{{-     "[<]" -}}
{{-   end -}}
{{- end -}}

{{- if eq .Format "pdf" -}}
{{-   $bodyTitle := default "Notes" .BodyTitle -}}
{{-   $noteTitle := trim .NoteTitle -}}
{{-   $noteNumber := printf "%d" .NoteNumber -}}
{{-   $label := "" -}}
{{-   if gt .BodyNumber 0 -}}
{{-     $label = printf "%d.%s" .BodyNumber $noteNumber -}}
{{-   else -}}
{{-     $label = $noteNumber -}}
{{-   end -}}
{{-   if and $noteTitle (regexMatch "[^0-9[:space:]]" $noteTitle) -}}
{{-     printf "%s: %s" $bodyTitle $noteTitle -}}
{{-   else -}}
{{-     printf "%s: %s" $bodyTitle $label -}}
{{-   end -}}
{{- else -}}
{{-   if gt .BodyNumber 0 -}}
{{-     printf "%d" .BodyNumber -}}.
{{-   end -}}
{{-   printf "%d" .NoteNumber -}}
{{- end -}}

{{- $names := list -}}
{{- range .Authors -}}
{{-   $name := list -}}
{{-   if .FirstName -}}{{ $name = append $name .FirstName -}}{{- end -}}
{{-   if .MiddleName -}}{{ $name = append $name .MiddleName -}}{{- end -}}
{{-   if .LastName -}}{{ $name = append $name .LastName }}{{- end -}}
{{-   if and (not $name) .Nickname -}}{{ $name = append $name .Nickname }}{{- end -}}
{{-   $names = append $names (join " " $name) -}}
{{- end -}}
{{- join ", " $names -}}
